*{box-sizing:border-box}body{margin:20px;color:#111;font:11px Arial,sans-serif}.toolbar{display:flex;justify-content:space-between;margin-bottom:16px}.toolbar a,.toolbar button{padding:8px 12px;background:#102d4f;color:#fff;border:0;text-decoration:none;cursor:pointer}.heading{text-align:center;margin-bottom:20px}.heading h1{font-size:17px;background:#000;color:#fff;padding:7px;margin:8px auto 3px}.heading p{margin:4px}.table-wrap{overflow:visible}table{border-collapse:collapse;width:100%}th,td{border:1px solid #111;text-align:center;padding:5px 4px}th{background:#ddd}th:first-child,td:first-child,th:nth-child(2),td:nth-child(2){text-align:left}.absent{color:#a00}.footer{margin-top:18px;text-align:right}@media print{body{margin:8mm}.toolbar{display:none}thead{display:table-header-group}tr{break-inside:avoid}th,td{padding:4px 2px;font-size:9px}}
</style></head><body><div class="toolbar"><a href="{{ route('examination.result-sheet', ['class_id' => $classId, 'month' => $month]) }}">Back to results</a><button onclick="window.print()">Print result sheet</button></div><header class="heading"><strong>{{ $academy?->name ?? 'Academy' }}</strong><p>{{ $academy?->address ?? '' }}</p><h1>Result Sheet · {{ $classes->firstWhere('id', $classId)?->name }} {{ $classes->firstWhere('id', $classId)?->section }}</h1><strong>Result month: {{ \Illuminate\Support\Carbon::createFromFormat('Y-m', $month)->format('F Y') }}</strong></header><div class="table-wrap"><table><thead><tr><th>Student name</th><th>Student ID</th>@foreach ($examinations as $exam)<th>{{ $exam->subject }}<br>{{ $exam->title }}<br>({{ $exam->total_marks }})</th>@endforeach<th>Total</th><th>%</th><th>Rank</th></tr></thead><tbody>@php($ranked = $students->map(function ($student) use ($examinations) { $obtained = 0; $possible = 0; foreach ($examinations as $exam) { $mark = $student->selected_results[$exam->id] ?? null; if ($mark && (float) $mark->marks_obtained >= 0) { $obtained += (float) $mark->marks_obtained; $possible += (float) $exam->total_marks; } } $student->result_total = $obtained; $student->result_possible = $possible; $student->result_percent = $possible > 0 ? $obtained / $possible * 100 : 0; return $student; })->sortByDesc('result_percent')->values())@foreach ($ranked as $position => $student)<tr><td>{{ $student->name }}</td><td>{{ $student->admission_no }}</td>@foreach ($examinations as $exam)@php($mark = $student->selected_results[$exam->id] ?? null)<td class="{{ $mark && (float) $mark->marks_obtained < 0 ? 'absent' : '' }}">{{ $mark ? ((float) $mark->marks_obtained < 0 ? 'A' : rtrim(rtrim(number_format((float) $mark->marks_obtained, 2), '0'), '.')) : '—' }}</td>@endforeach<td>{{ rtrim(rtrim(number_format($student->result_total, 2), '0'), '.') }}/{{ rtrim(rtrim(number_format($student->result_possible, 2), '0'), '.') }}</td><td>{{ number_format($student->result_percent, 2) }}%</td><td>{{ $position + 1 }}</td></tr>@endforeach</tbody></table></div><p class="footer">Printed {{ now()->timezone('Asia/Karachi')->format('d M Y, h:i A') }}</p><script>window.addEventListener('load',()=>window.print())</script></body></html>
